from minidb.types import (
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    InsertStmt,
    QueryResult,
    Schema,
    SelectStmt,
    Statement,
    StorageBackend,
    TypeMismatchError,
    UnknownColumnError,
    WhereMatcher,
)


def execute(stmt: Statement, store: StorageBackend, matches: WhereMatcher) -> QueryResult:
    if isinstance(stmt, CreateTableStmt):
        return execute_create(stmt, store)
    elif isinstance(stmt, DropTableStmt):
        return execute_drop(stmt, store)
    elif isinstance(stmt, InsertStmt):
        return execute_insert(stmt, store)
    elif isinstance(stmt, SelectStmt):
        return execute_select(stmt, store, matches)
    elif isinstance(stmt, DeleteStmt):
        return execute_delete(stmt, store, matches)
    else:
        raise TypeError(f"Unknown statement type: {type(stmt)}")


def execute_create(stmt: CreateTableStmt, store: StorageBackend) -> QueryResult:
    store.create_table(stmt.table, Schema(stmt.columns))
    return QueryResult()


def execute_drop(stmt: DropTableStmt, store: StorageBackend) -> QueryResult:
    store.drop_table(stmt.table)
    return QueryResult()


def execute_insert(stmt: InsertStmt, store: StorageBackend) -> QueryResult:
    schema = store.get_schema(stmt.table)
    if stmt.columns is None:
        row = stmt.values
    else:
        if len(stmt.columns) != len(stmt.values):
            raise TypeMismatchError("Value count mismatch")
        row = [None] * len(schema)
        for col_name, value in zip(stmt.columns, stmt.values):
            idx = schema.index_of(col_name)
            row[idx] = value
    store.insert(stmt.table, tuple(row))
    return QueryResult(row_count=1)


def execute_select(stmt: SelectStmt, store: StorageBackend, matches: WhereMatcher) -> QueryResult:
    schema = store.get_schema(stmt.table)
    if stmt.columns is None:
        columns = schema.column_names()
    else:
        columns = list(stmt.columns)
        for col in columns:
            schema.index_of(col)
    rows = store.scan(stmt.table)
    if stmt.where is not None:
        rows = [row for row in rows if matches(stmt.where, row, schema)]
    projected_rows = [[row[schema.index_of(col)] for col in columns] for row in rows]
    return QueryResult(columns=columns, rows=projected_rows, row_count=len(projected_rows))


def execute_delete(stmt: DeleteStmt, store: StorageBackend, matches: WhereMatcher) -> QueryResult:
    schema = store.get_schema(stmt.table)
    if stmt.where is None:
        predicate = lambda row: True
    else:
        predicate = lambda row: matches(stmt.where, row, schema)
    row_count = store.delete_where(stmt.table, predicate)
    return QueryResult(row_count=row_count)

